        ea:CourseGranularity
        ea:AcademicProgramGranularity
        ea:InstitutionalGranularity
        ea:EducationalSystemGranularity
    ) .

ea:IndividualLearnerGranularity a owl:Class ; rdfs:label "Individual Learner Granularity"@en ; rdfs:subClassOf ea:AssessmentGranularity .
ea:LearningCommunityGranularity a owl:Class ; rdfs:label "Learning Community Granularity"@en ; rdfs:subClassOf ea:AssessmentGranularity .
ea:CourseGranularity a owl:Class ; rdfs:label "Course Granularity"@en ; rdfs:subClassOf ea:AssessmentGranularity .
ea:AcademicProgramGranularity a owl:Class ; rdfs:label "Academic Program Granularity"@en ; rdfs:subClassOf ea:AssessmentGranularity .
ea:InstitutionalGranularity a owl:Class ; rdfs:label "Institutional Granularity"@en ; rdfs:subClassOf ea:AssessmentGranularity .
ea:EducationalSystemGranularity a owl:Class ; rdfs:label "Educational System Granularity"@en ; rdfs:subClassOf ea:AssessmentGranularity .

